CREATE FUNCTION public.can_manage_system_red_flags() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.employees e ON e.auth_user_id=r.user_id WHERE r.user_id=auth.uid() AND lower(r.role) IN ('admin','administrator','super admin','managing director') AND e.status='Active' AND NOT coalesce(e.disabled,false)); $$;
REVOKE ALL ON FUNCTION public.can_manage_system_red_flags() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_manage_system_red_flags() TO authenticated,service_role;
CREATE FUNCTION public.red_flag_missing_analysis(has_sampling boolean,has_file boolean) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(has_sampling,false) AND NOT coalesce(has_file,false); $$;
CREATE FUNCTION public.red_flag_form_key(value text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT nullif(lower(btrim(value)),''); $$;
CREATE TABLE public.system_red_flags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),fingerprint text NOT NULL UNIQUE,rule_key text NOT NULL,department text NOT NULL,severity text NOT NULL,title text NOT NULL,details jsonb NOT NULL DEFAULT '{}',review_path text NOT NULL,status text NOT NULL DEFAULT 'open',assigned_to uuid,review_notes text,first_detected_at timestamptz NOT NULL DEFAULT now(),last_detected_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.system_red_flags TO authenticated; GRANT ALL ON public.system_red_flags TO service_role;
ALTER TABLE public.system_red_flags ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_flags ON public.system_red_flags FOR SELECT TO authenticated USING(public.can_manage_system_red_flags());
CREATE FUNCTION public.touch_system_red_flag() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER touch_system_red_flags BEFORE UPDATE ON public.system_red_flags FOR EACH ROW EXECUTE FUNCTION public.touch_system_red_flag();
CREATE INDEX system_red_flags_status ON public.system_red_flags(status,last_detected_at);
CREATE VIEW public.system_red_flag_candidates WITH (security_invoker=true) AS
SELECT 'quality_missing_analysis:'||q.id fingerprint,'quality_missing_analysis'::text rule_key,'Quality'::text department,'high'::text severity,'Sampling-linked assessment has no attached analysis form'::text title,jsonb_build_object('assessment_id',q.id,'batch',q.batch_number,'form_number',q.form_number,'recorded_by',q.assessed_by,'sampling_order',q.sampling_order_number,'delivery_id',q.store_record_id,'action','Check the saved attachment and sampling linkage; upload or link the correct analysis form.') details,'/quality-control'::text review_path
FROM public.quality_assessments q WHERE public.red_flag_missing_analysis(EXISTS(SELECT 1 FROM public.quality_sampling_orders s WHERE s.id=q.sampling_order_id OR (nullif(btrim(q.store_record_id),'') IS NOT NULL AND s.linked_store_record_id=q.store_record_id) OR (nullif(btrim(q.sampling_order_number),'') IS NOT NULL AND s.order_number=q.sampling_order_number)),EXISTS(SELECT 1 FROM public.quality_analysis_files f WHERE f.id=q.analysis_file_id AND nullif(btrim(f.file_path),'') IS NOT NULL))
UNION ALL
SELECT 'clearance_duplicate:'||public.red_flag_form_key(form_number),'clearance_duplicate','Store','high','Store clearance form number used more than once',jsonb_build_object('form_number',public.red_flag_form_key(form_number),'records',jsonb_agg(jsonb_build_object('id',id,'date',clearance_date,'warehouse',warehouse,'buyer',destination_buyer,'recorded_by',created_by)),'action','Review both clearances and correct the duplicate number; do not delete legitimate dispatches.'),'/store' FROM public.store_clearance_forms WHERE public.red_flag_form_key(form_number) IS NOT NULL GROUP BY public.red_flag_form_key(form_number) HAVING count(*)>1
UNION ALL
SELECT 'quality_sampling_missing:'||q.id,'quality_sampling_missing','Quality','high','Assessment points to a missing sampling order',jsonb_build_object('assessment_id',q.id,'batch',q.batch_number,'sampling_order_id',q.sampling_order_id,'action','Verify the original sampling order and repair the saved link.'),'/quality-control' FROM public.quality_assessments q WHERE q.sampling_order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.quality_sampling_orders s WHERE s.id=q.sampling_order_id)
UNION ALL
SELECT 'procurement_source_missing:'||p.id,'procurement_source_missing','Procurement','high','Procurement review has no matching source request',jsonb_build_object('review_id',p.id,'source_table',p.source_table,'record_id',p.record_id,'title',p.request_title,'reviewed_by',p.reviewed_by,'action','Check whether the source request was legitimately removed; reconcile the review reference.'),'/procurement-review' FROM public.procurement_reviews p WHERE (p.source_table='approval_requests' AND NOT EXISTS(SELECT 1 FROM public.approval_requests a WHERE a.id::text=p.record_id)) OR (p.source_table='provider_submission_requests' AND NOT EXISTS(SELECT 1 FROM public.provider_submission_requests a WHERE a.id::text=p.record_id))
UNION ALL
SELECT 'booking_overdelivered:'||b.id,'booking_overdelivered','Procurement','high','Recorded booking deliveries exceed the booked quantity',jsonb_build_object('booking_id',b.id,'supplier',b.supplier_name,'booked_kg',b.booked_quantity_kg,'delivered_kg',b.delivered_quantity_kg,'action','Reconcile deliveries and the supplier booking quantity.'),'/coffee-bookings' FROM public.coffee_bookings b WHERE b.delivered_quantity_kg>b.booked_quantity_kg
UNION ALL
SELECT 'inventory_invalid_balance:'||b.id,'inventory_invalid_balance','Inventory','critical','Batch remaining stock is outside its received weight',jsonb_build_object('batch_id',b.id,'batch',b.batch_code,'received_kg',b.total_kilograms,'remaining_kg',b.remaining_kilograms,'action','Review batch sources and sales allocations before making a stock correction.'),'/inventory' FROM public.inventory_batches b WHERE b.remaining_kilograms<0 OR b.remaining_kilograms>b.total_kilograms
UNION ALL
SELECT 'finance_paid_balance:'||f.id,'finance_paid_balance','Finance','critical','Lot marked paid still has an outstanding balance',jsonb_build_object('lot_id',f.id,'batch',f.batch_number,'balance_ugx',f.balance_ugx,'paid_ugx',f.amount_paid_ugx,'action','Reconcile recorded payments and balance; do not send another payout until checked.'),'/finance' FROM public.finance_coffee_lots f WHERE lower(f.payment_status)='paid' AND f.balance_ugx>0
UNION ALL
SELECT 'treasury_alert:'||t.id,'treasury_alert','Treasury','critical',t.message,jsonb_build_object('alert_id',t.id,'account',t.account_code,'alert_type',t.alert_type,'reference',t.reference,'action','Review the existing Treasury alert and reconcile or fund the affected account.'),'/admin/treasury' FROM public.treasury_alerts t WHERE t.resolved_at IS NULL;
REVOKE ALL ON public.system_red_flag_candidates FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.system_red_flag_candidates TO service_role;
CREATE FUNCTION public.scan_system_red_flags() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c record; flag_id uuid; n integer:=0; was_resolved boolean; BEGIN IF pg_trigger_depth()=0 AND auth.role() IS DISTINCT FROM 'service_role' AND session_user NOT IN ('postgres','supabase_admin') AND NOT public.can_manage_system_red_flags() THEN RAISE EXCEPTION 'Administrator access required'; END IF; PERFORM pg_advisory_xact_lock(hashtext('system_red_flags_scan')); CREATE TEMP TABLE IF NOT EXISTS current_red_flags (fingerprint text,rule_key text,department text,severity text,title text,details jsonb,review_path text) ON COMMIT DROP; TRUNCATE pg_temp.current_red_flags; INSERT INTO pg_temp.current_red_flags SELECT * FROM public.system_red_flag_candidates; FOR c IN SELECT * FROM pg_temp.current_red_flags LOOP SELECT id,status='resolved' INTO flag_id,was_resolved FROM public.system_red_flags WHERE fingerprint=c.fingerprint; IF flag_id IS NULL THEN INSERT INTO public.system_red_flags(fingerprint,rule_key,department,severity,title,details,review_path) VALUES(c.fingerprint,c.rule_key,c.department,c.severity,c.title,c.details,c.review_path) RETURNING id INTO flag_id; n:=n+1; ELSIF was_resolved THEN UPDATE public.system_red_flags SET status='open',resolved_at=NULL,assigned_to=NULL,last_detected_at=now(),details=c.details WHERE id=flag_id; n:=n+1; ELSE UPDATE public.system_red_flags SET last_detected_at=now(),details=c.details,title=c.title WHERE id=flag_id; END IF; IF NOT EXISTS(SELECT 1 FROM public.notifications WHERE type='system_red_flag' AND message LIKE '%'||flag_id::text||'%') OR was_resolved THEN INSERT INTO public.notifications(title,message,type,priority,target_user_id) SELECT c.title,c.department||': review required. Open Administrator Hub → System red flags. Task '||flag_id::text,'system_red_flag',CASE WHEN c.severity='critical' THEN 'urgent' ELSE 'high' END,r.user_id FROM (SELECT DISTINCT user_id FROM public.user_roles WHERE lower(role) IN ('admin','administrator','super admin','managing director'))r WHERE EXISTS(SELECT 1 FROM public.employees e WHERE e.auth_user_id=r.user_id AND e.status='Active' AND NOT coalesce(e.disabled,false)); END IF; END LOOP; UPDATE public.system_red_flags f SET status='resolved',resolved_at=now() WHERE status<>'resolved' AND NOT EXISTS(SELECT 1 FROM pg_temp.current_red_flags c WHERE c.fingerprint=f.fingerprint); RETURN jsonb_build_object('ok',true,'new_flags',n,'checked_at',now()); END; $$;
REVOKE ALL ON FUNCTION public.scan_system_red_flags() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.scan_system_red_flags() TO authenticated,service_role;
CREATE FUNCTION public.review_system_red_flag(p_id uuid,p_notes text,p_claim boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_system_red_flags() THEN RAISE EXCEPTION 'Administrator access required'; END IF; UPDATE public.system_red_flags SET review_notes=nullif(btrim(p_notes),''),assigned_to=CASE WHEN p_claim THEN auth.uid() ELSE assigned_to END,status=CASE WHEN p_claim THEN 'in_progress' ELSE status END WHERE id=p_id AND status<>'resolved' AND (assigned_to IS NULL OR assigned_to=auth.uid()); IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','Task is resolved or already assigned to another administrator'); END IF; RETURN jsonb_build_object('ok',true); END; $$;
REVOKE ALL ON FUNCTION public.review_system_red_flag(uuid,text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_system_red_flag(uuid,text,boolean) TO authenticated;
CREATE FUNCTION public.detect_system_red_flags_on_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.scan_system_red_flags(); RETURN NULL; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Red flag scan failed: %',SQLERRM; RETURN NULL; END; $$;
REVOKE ALL ON FUNCTION public.detect_system_red_flags_on_change() FROM PUBLIC;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['quality_assessments','quality_sampling_orders','quality_analysis_files','store_clearance_forms','procurement_reviews','approval_requests','provider_submission_requests','coffee_bookings','inventory_batches','finance_coffee_lots','treasury_alerts'] LOOP EXECUTE format('CREATE TRIGGER system_red_flags_on_change AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION public.detect_system_red_flags_on_change()',t); END LOOP; END; $$;